private func checkTestVersion() {
    #if DEBUG || RELEASE_NIGHTLY
    Task { @MainActor in
        do {
            let version = try await middlewareConfigurationProvider.libraryVersion()
            let isUnstableVersion = !version.hasPrefix("v")
            if isUnstableVersion {
                if (basicUserInfoStorage.usersId.isEmpty || userDefaults.showUnstableMiddlewareError) {
                    showWarningAlert.toggle()
                } else {
                    showLoginOrAuth()
                }
            } else {
                showLoginOrAuth()
                userDefaults.showUnstableMiddlewareError = true
            }

final class UserDefaultsStorage: UserDefaultsStorageProtocol, @unchecked Sendable {
    @UserDefault("showUnstableMiddlewareError", defaultValue: true)
    var showUnstableMiddlewareError: Bool

@propertyWrapper
public struct UserDefault<T: Codable & Sendable>: Sendable {
    private let storage: UserDefaultStorage<T>

    public init(_ key: String, defaultValue: T) {
        self.storage = UserDefaultStorage(key: key, defaultValue: defaultValue)
    }

    public var wrappedValue: T {
        get { storage.value }
        set { storage.value = newValue }
    }

public init(key: String, defaultValue: T) {
    self.key = key
    self.defaultValue = defaultValue

    // Read value from UserDefaults
    if let data = UserDefaults.standard.object(forKey: key) as? Data,
       let value = try? JSONDecoder().decode(T.self, from: data) {
        self.data = value
    } else {
        self.data = defaultValue
    }

public var value: T {
    get {
        lock.lock()
        defer { lock.unlock() }
        return data
    }
    set {
        lock.lock()
        defer { lock.unlock() }

        data = newValue

        if let optional = newValue as? AnyOptional, optional.isNil {
            UserDefaults.standard.removeObject(forKey: key)
        } else {
            // Convert newValue to data
            let data = try? JSONEncoder().encode(newValue)

            // Set value to UserDefaults
            UserDefaults.standard.set(data, forKey: key)
        }

var userDefaultsStorage: Factory< any UserDefaultsStorageProtocol> {
    self { UserDefaultsStorage() }.singleton
}
